// Members of App. Linking changes the gallery index only; generation output stays unchanged.
std::thread migrationThread;std::atomic_bool migrationCancel{false};bool migrationRunning=false;
std::map<fs::path,fs::path> migrationFiles;std::string migrationCacheKey;
void unlinkMigrationGallery(){if(migrationFiles.count(selected)){selected.clear();preview.Reset();store->state["selected"]=nullptr;}store->state.erase("_gallery_migrations");migrationFiles.clear();migrationCacheKey.clear();store->save();scan();status=L"이관 자료 연결을 해제했습니다.";}
void exportMigrationContext(){if(store->workspaceScope.empty())throw std::runtime_error("로그인 후 이관 정보를 저장하세요.");auto file=fileDialog(hwnd,true,L"이관 정보 JSON\0*.json\0\0",L"migration-context.json");if(file.empty())return;atomicWrite(file,json{{"format",1},{"user",store->workspaceScope},{"channel",store->active},{"mode",hardcore()?"hardcore":"safe"}}.dump(2));status=L"현재 계정·채널의 이관 정보를 저장했습니다.";}

void attachMigration(){if(copyMigrationBusy||copyMigrationActive||migrationRunning)throw std::runtime_error("이관 파일을 검사 중입니다.");if(store->workspaceScope.empty())throw std::runtime_error("로그인 후 이관 자료를 연결하세요.");auto selected=pickFolder(hwnd);if(selected.empty())return;auto target=fs::path(selected);auto row=migrationRecord(target,store->workspaceScope,store->active);auto bindings=store->state.value("_gallery_migrations",json::array());if(!bindings.is_array()||bindings.size()>=16)throw std::runtime_error("채널당 이관 폴더는 16개까지 연결할 수 있습니다.");for(auto& binding:bindings)if(migrationSamePath(target,wide(str(binding,"target"))))throw std::runtime_error("이미 연결된 이관 폴더입니다.");auto prompt=L"현재 채널에 이관 자료를 연결할까요?\n"+std::to_wstring(row["entries"].size())+L"개 파일을 검사합니다.\n원본과 새 이미지 저장 폴더는 그대로 유지됩니다.";if(MessageBoxW(hwnd,prompt.c_str(),L"이관 자료 연결",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;save();if(migrationThread.joinable())migrationThread.join();migrationCancel=false;migrationRunning=true;auto scope=store->workspaceScope,channel=store->active;auto* targetEngine=engine;
 migrationThread=std::thread([this,target,scope,channel,targetEngine]{json payload={{"scope",scope},{"channel",channel}};ULONGLONG last=0;try{payload["binding"]=verifyMigration(target,scope,channel,migrationCancel,[&](size_t done,size_t count){auto now=GetTickCount64();if(now-last<200&&done!=count)return;last=now;targetEngine->event({"migration_progress","","",{{"scope",scope},{"channel",channel},{"done",done},{"count",count}}});});}catch(const std::exception&){payload["error"]=migrationCancel?"이관 연결을 취소했습니다.":"이관 파일 검사에 실패했습니다. 원본을 보존하고 복사 기록과 파일을 확인하세요.";}targetEngine->event({"migration_ready","","",payload});});status=L"이관 파일 검사 중…";
}
void migrationReply(const Event& event){if(event.kind=="migration_ready")migrationRunning=false;if(str(event.data,"scope")!=store->workspaceScope||str(event.data,"channel")!=store->active)return;if(event.kind=="migration_progress"){status=L"이관 파일 검사 "+std::to_wstring(event.data.value("done",size_t(0)))+L" / "+std::to_wstring(event.data.value("count",size_t(0)));return;}if(event.data.contains("error")){status=wide(str(event.data,"error"));return;}auto binding=event.data.value("binding",json::object());json current;try{current=migrationRecord(wide(str(binding,"target")),store->workspaceScope,store->active,binding);}catch(...){status=L"이관 기록이 변경됐습니다. 다시 연결하세요.";return;}auto& list=store->state["_gallery_migrations"];if(!list.is_array())list=json::array();bool found=false;for(auto& old:list)if(str(old,"transaction")==str(binding,"transaction"))found=true;if(!found)list.push_back(current["binding"]);store->save();scan();status=L"이관 자료를 연결했습니다.";}
void detachMigrations(){if(migrationRunning){migrationCancel=true;status=L"이관 연결 취소 중…";return;}if(MessageBoxW(hwnd,L"이 채널의 이관 자료 연결을 해제할까요?\n이미지·JSON·원본 파일은 삭제하지 않습니다.",L"이관 연결 해제",MB_YESNO|MB_ICONQUESTION)!=IDYES)return;unlinkMigrationGallery();}
